import sys
import json
import re
from html import escape

def evaluate_expression(expr, context):
    try:
        return eval(expr, {'__builtins__': None}, context)
    except Exception as e:
        raise ValueError(f"Error evaluating expression '{expr}': {e}")

def process_template(template_path, json_data):
    with open(template_path, 'r') as f:
        template = f.read()

    processed = []
    for match in re.finditer(r'\{\{([^}]+)\}\}', template):
        expr = match.group(1)
        try:
            value = evaluate_expression(expr, json_data)
            processed.append(match.group(0).replace('{{', '').replace('}}', str(value)))
        except ValueError as e:
            processed.append(match.group(0))
            print(f"Warning: {e}", file=sys.stderr)
    else:
        processed.append(template)

    return ''.join(processed)

def main():
    if len(sys.argv) != 3:
        print("Usage: python script.py <template_file> <json_file>", file=sys.stderr)
        sys.exit(1)

    template_path = sys.argv[1]
    json_path = sys.argv[2]

    try:
        with open(json_path, 'r') as f:
            json_data = json.load(f)
    except json.JSONDecodeError as e:
        print(f"Error parsing JSON file: {e}", file=sys.stderr)
        sys.exit(1)

    processed_html = process_template(template_path, json_data)
    print(processed_html)

if __name__ == "__main__":
    main()

import json
import re
import sys
import ast

def evaluate_expression(expr, variables):
    try:
        # Safely evaluate the expression using the provided variables
        return ast.literal_eval(expr)
    except (SyntaxError, ValueError):
        # Fallback to eval with restricted globals and locals
        safe_globals = {'__builtins__': None}
        safe_locals = {'__builtins__': None}
        safe_locals.update(variables)
        return eval(expr, safe_globals, safe_locals)

def process_template(template_path, json_data):
    with open(template_path, 'r') as f:
        html_template = f.read()

    # Parse JSON data
    try:
        variables = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON data provided")

    # Replace placeholders with evaluated expressions
    def replace_placeholder(match):
        expr = match.group(1)
        try:
            return str(evaluate_expression(expr, variables))
        except Exception as e:
            return f"{{{expr}}}"  # Fallback to original if evaluation fails

    # Use regex to find all {{expression}} patterns
    processed_html = re.sub(r'\{\{(.*?)\}\}', replace_placeholder, html_template)
    return processed_html

if __name__ == "__main__":
