import sys
import json
import re

def evaluate_expression(expression, context):
    # Evaluate the expression in the context of the provided variables
    return eval(expression, {}, context)

def replace_expressions(template, context):
    # Function to replace all occurrences of {{expression}} in the template
    def replacer(match):
        expression = match.group(1)  # Get the expression inside {{}}
        try:
            # Evaluate the expression and return its string form
            result = evaluate_expression(expression, context)
            return str(result)
        except Exception as e:
            return f'{{{{ERROR: {str(e)}}}}}'  # Return error message if evaluation fails

    # Use regex to find all {{expression}} patterns
    pattern = re.compile(r'{{(.*?)}}')
    return pattern.sub(replacer, template)

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python script.py <template_file>')
        sys.exit(1)

    template_file_path = sys.argv[1]

    # Read the JSON object from stdin
    json_input = sys.stdin.read()
    context = json.loads(json_input)

    # Read the template file
    with open(template_file_path, 'r') as template_file:
        template = template_file.read()

    # Replace expressions in the template
    result = replace_expressions(template, context)

    # Print the resulting HTML
    print(result)
